import os, json, re
import numpy as np

# Inputs (Scientia sets-only exports per mail)
P_K1E9  = 'storage/Scientia/nmap/n26/exports_for_noesis_ii/scientia_sota_528_top_k_slack_1e9.json'
P_K1E8  = 'storage/Scientia/nmap/n26/exports_for_noesis_ii/scientia_sota_528_top_k_slack_1e8.json'

# Noesis snapshot (geometry for crossing test) and boundary tol
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
TOL_BOUND = 1e-8

OUT_JSON = 'storage/noesis/nmap/scientia_eval528_dualtol_gate_on_noesis.json'
N = 26

# ---------------- Parsers ----------------
def read_json_any(path):
    if not os.path.exists(path):
        return None
    try:
        with open(path, 'r') as f:
            return json.load(f)
    except Exception:
        return None

def json_to_pair_set(obj):
    S = set()
    if obj is None: return S
    data = obj.get('items', obj.get('pairs', obj))
    if isinstance(data, dict): data = data.get('items', list(data.values()))
    if not isinstance(data, (list, tuple)): return S
    for e in data:
        i = j = None
        if isinstance(e, dict):
            for k in ('i','a','u','p','p1'):
                if k in e and e[k] not in (None,''):
                    try: i = int(str(e[k]).strip()); break
                    except Exception: pass
            for k in ('j','b','v','q','p2'):
                if k in e and e[k] not in (None,''):
                    try: j = int(str(e[k]).strip()); break
                    except Exception: pass
        elif isinstance(e, (list, tuple)) and len(e) >= 2:
            try:
                i = int(str(e[0]).strip()); j = int(str(e[1]).strip())
            except Exception:
                i = j = None
        if i is None or j is None: 
            continue
        if 0 <= i < N and 0 <= j < N and i != j:
            a,b = (i,j) if i<j else (j,i)
            S.add((a,b))
    # 1-based fallback
    if S and min(min(i,j) for (i,j) in S) >= 1 and max(max(i,j) for (i,j) in S) <= N:
        S = set((i-1, j-1) for (i,j) in S)
    return S

# ---------------- Geometry ----------------
def load_snapshot():
    c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
    r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    return c, r

def boundary_actives(c, r, tol=TOL_BOUND):
    x = c[:,0]; y = c[:,1]
    act = (x - r <= tol) | (1.0 - x - r <= tol) | (y - r <= tol) | (1.0 - y - r <= tol)
    return act

def seg_cross_strict(a, b, c, d, eps=0.0):
    # Proper intersection (excludes shared endpoints/collinearity)
    def orient(p, q, r):
        return (q[0]-p[0])*(r[1]-p[1]) - (q[1]-p[1])*(r[0]-p[0])
    o1 = orient(a,b,c); o2 = orient(a,b,d)
    o3 = orient(c,d,a); o4 = orient(c,d,b)
    return (o1*o2 < -eps) and (o3*o4 < -eps)

# ---------------- Main ----------------
def construct_packing():
    J1 = read_json_any(P_K1E9)
    J8 = read_json_any(P_K1E8)
    S1 = json_to_pair_set(J1)
    S8 = json_to_pair_set(J8)

    inter_pairs = S1 & S8  # dual-tolerance intersection (by index sets)
    c, r = load_snapshot()
    bmask = boundary_actives(c, r, tol=TOL_BOUND)

    # Interior filter at tol=1e-8 (Noesis geometry)
    interior_pairs = [(i,j) for (i,j) in inter_pairs if (not bmask[i] and not bmask[j])]

    # Search for disjoint crossing pairs on Noesis geometry
    cross_found = False
    example = None
    pts = c  # centers
    L = len(interior_pairs)
    for idx_a in range(L):
        i,j = interior_pairs[idx_a]
        for idx_b in range(idx_a+1, L):
            k,l = interior_pairs[idx_b]
            # must be disjoint
            if len({i,j,k,l}) < 4:
                continue
            if seg_cross_strict(pts[i], pts[j], pts[k], pts[l], eps=0.0):
                cross_found = True
                example = {'pair1': [i,j], 'pair2': [k,l]}
                break
        if cross_found:
            break

    out = {
        'scientia_eval_id': 528,
        'counts': {
            'k1e9': len(S1),
            'k1e8': len(S8),
            'intersection_dual_tol': len(inter_pairs),
            'intersection_interior_noesis': len(interior_pairs)
        },
        'gate_result': 'SAT' if cross_found else 'UNSAT',
        'example_crossing': example
    }
    try:
        os.makedirs(os.path.dirname(OUT_JSON), exist_ok=True)
        with open(OUT_JSON, 'w') as f:
            json.dump(out, f, indent=2)
        print('DUALTOL_GATE_JSON:', OUT_JSON)
        print('GATE_RESULT:', out['gate_result'])
        print('COUNTS:', out['counts'])
        if example: print('EXAMPLE:', example)
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    # Return baseline pack (with tiny final shrink) for a valid evaluation
    r_out = np.maximum(r - 1e-9, 1e-12)
    return c.astype(float), r_out.astype(float)
